CREATE TABLE WASM_IDENTITY (table_name VARCHAR(128) PRIMARY KEY, next_id BIGINT NOT NULL);
CREATE TABLE loyalty_tier_rule (tier VARCHAR(10) NOT NULL, min_spend DECIMAL(14,2) NOT NULL, points_multiplier DECIMAL(4,2) NOT NULL, PRIMARY KEY (tier));
CREATE TABLE customer (customer_id INT NOT NULL, first_name VARCHAR(60) NOT NULL, last_name VARCHAR(60) NOT NULL, email VARCHAR(120) NOT NULL, phone VARCHAR(30), date_of_birth DATE, nationality VARCHAR(2), segment VARCHAR(20) NOT NULL, loyalty_tier VARCHAR(10) NOT NULL, loyalty_points INT NOT NULL, marketing_opt_in SMALLINT NOT NULL, status VARCHAR(10) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, PRIMARY KEY (customer_id));
INSERT INTO WASM_IDENTITY VALUES ('customer', 0);
CREATE TABLE address (address_id INT NOT NULL, customer_id INT NOT NULL, addr_type VARCHAR(10) NOT NULL, line1 VARCHAR(120) NOT NULL, city VARCHAR(60) NOT NULL, postcode VARCHAR(20), country VARCHAR(2) NOT NULL, is_primary SMALLINT NOT NULL, PRIMARY KEY (address_id));
INSERT INTO WASM_IDENTITY VALUES ('address', 0);
CREATE TABLE product (product_id INT NOT NULL, sku VARCHAR(20) NOT NULL, name VARCHAR(100) NOT NULL, category VARCHAR(20) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, stock_qty INT NOT NULL, active SMALLINT NOT NULL, PRIMARY KEY (product_id));
INSERT INTO WASM_IDENTITY VALUES ('product', 0);
CREATE TABLE orders (order_id INT NOT NULL, customer_id INT NOT NULL, order_date TIMESTAMP(6) NOT NULL, status VARCHAR(10) NOT NULL, channel VARCHAR(10) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, currency VARCHAR(3) NOT NULL, PRIMARY KEY (order_id));
INSERT INTO WASM_IDENTITY VALUES ('orders', 0);
CREATE TABLE order_item (order_item_id INT NOT NULL, order_id INT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, line_total DECIMAL(12,2) NOT NULL, PRIMARY KEY (order_item_id));
INSERT INTO WASM_IDENTITY VALUES ('order_item', 0);
CREATE TABLE payment (payment_id INT NOT NULL, order_id INT NOT NULL, method VARCHAR(10) NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(10) NOT NULL, paid_at TIMESTAMP(6) NOT NULL, PRIMARY KEY (payment_id));
INSERT INTO WASM_IDENTITY VALUES ('payment', 0);
CREATE TABLE interaction (interaction_id INT NOT NULL, customer_id INT NOT NULL, channel VARCHAR(10) NOT NULL, type VARCHAR(20) NOT NULL, subject VARCHAR(200), sentiment SMALLINT NOT NULL, status VARCHAR(10) NOT NULL, opened_at TIMESTAMP(6) NOT NULL, closed_at TIMESTAMP(6), PRIMARY KEY (interaction_id));
INSERT INTO WASM_IDENTITY VALUES ('interaction', 0);
CREATE TABLE loyalty_txn (txn_id INT NOT NULL, customer_id INT NOT NULL, order_id INT, points INT NOT NULL, reason VARCHAR(20) NOT NULL, txn_date TIMESTAMP(6) NOT NULL, PRIMARY KEY (txn_id));
INSERT INTO WASM_IDENTITY VALUES ('loyalty_txn', 0);
CREATE TABLE customer_score (customer_id INT NOT NULL, churn_score INT NOT NULL, risk_band VARCHAR(10) NOT NULL, scored_at TIMESTAMP(6) NOT NULL, PRIMARY KEY (customer_id));
